CREATE OR REPLACE FUNCTION public.update_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
 begin
 new.updated_at = now();
 return new;
 end;
 $function$

CREATE OR REPLACE FUNCTION public.reply_to_review(target_review_id uuid, reply_text text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
 if not exists (
 select 1
 from public.reviews r
 join public.fonditas f on f.id = r.fondita_id
 where r.id = target_review_id
 and lower(f.telefono) = lower(auth.jwt() ->> 'email')
 ) then
 raise exception 'not authorized';
 end if;

 if char_length(trim(reply_text)) not between 1 and 600 then
 raise exception 'invalid reply';
 end if;

 update public.reviews
 set business_reply = trim(reply_text),
 business_replied_at = now()
 where id = target_review_id
 and status = 'published';
end;
$function$
